import math
# Compact DSL. Every icon: outline (silhouette, filled in solid/duotone/bulk) + detail (drawn over; cut out of solid).
# sw=N : line-shape rendered as an N-wide stroke in filled styles (solid/duotone/bulk). L = bold line width for line-only glyphs.
L = 2.6
def rr(x,y,w,h,r,**k): return dict(k="rect",x=x,y=y,w=w,h=h,r=r,**k)
def c(cx,cy,r,**k): return dict(k="circle",cx=cx,cy=cy,r=r,**k)
def p(d,**k): return dict(k="path",d=d,**k)
def ln(d,w=L,**k): return dict(k="path",d=d,sw=w,**k)
def dot(x,y): return dict(k="path",d=f"M{x} {y}h.01",dot=True)
def I(outline, detail=(), cat="", tags=""): return dict(outline=list(outline), detail=list(detail), cat=cat, tags=tags)

def gear_path(teeth=8, ro=9.5, ri=7.8, cx=12, cy=12):
    pts=[]
    for i in range(teeth*2):
        a0=math.pi*2*i/(teeth*2); a1=math.pi*2*(i+1)/(teeth*2)
        r = ro if i%2==0 else ri
        for t in (a0+0.06, a1-0.06):
            pts.append(f"{cx+r*math.cos(t):.2f} {cy+r*math.sin(t):.2f}")
    return "M"+"L".join(pts)+"z"

def star_path(n=5, ro=9.2, ri=4.3, cx=12, cy=12.6):
    pts=[]
    for i in range(n*2):
        a=-math.pi/2+math.pi*i/n; r=ro if i%2==0 else ri
        pts.append(f"{cx+r*math.cos(a):.2f} {cy+r*math.sin(a):.2f}")
    return "M"+"L".join(pts)+"z"

